        tex: "\\begin{gathered} \\text{równoległobok:} \\\\ P = a \\cdot h \\end{gathered} \\qquad \\begin{gathered} \\text{romb:} \\\\ P = a \\cdot h \\\\ P = \\frac{e \\cdot f}{2} \\end{gathered}",
        rysunek: `<svg viewBox="0 0 300 160"><path class="l" d="M35 130L205 130L260 40L90 40Z"/><path class="a" d="M90 40L90 130"/><path class="l" d="M98 130L98 122L90 122"/><text class="ta" x="99" y="92" text-anchor="middle">h</text><text class="t" x="120" y="148" text-anchor="middle">a</text></svg>`,
        litery: "$a$ – bok, $h$ – wysokość opuszczona na ten bok (prostopadła do niego), $e$, $f$ – przekątne rombu",
