        tex: "\\begin{array}{ll} \\text{kwadrat} & 4 \\\\ \\text{prostokąt} & 2 \\\\ \\text{romb} & 2 \\\\ \\text{trapez równoramienny} & 1 \\\\ \\text{deltoid} & 1 \\\\ \\text{równoległobok} & 0 \\end{array}",
        rysunek: `<svg viewBox="0 0 310 120"><path class="l" d="M20 100L90 100L90 30L20 30Z"/><path class="p" d="M55 22L55 108"/><path class="p" d="M12 65L98 65"/><path class="p" d="M16 26L94 104"/><path class="p" d="M16 104L94 26"/><path class="l" d="M125 95L215 95L215 45L125 45Z"/><path class="p" d="M170 37L170 103"/><path class="p" d="M117 70L223 70"/><path class="l" d="M250 70L275 30L300 70L275 110Z"/><path class="p" d="M275 22L275 118"/><path class="p" d="M242 70L308 70"/><text class="ta" x="55" y="120" text-anchor="middle">4</text><text class="ta" x="170" y="120" text-anchor="middle">2</text><text class="ta" x="275" y="120" text-anchor="middle">2</text></svg>`,
