        tex: "\\begin{array}{ll} \\text{równoboczny} & 3 \\\\ \\text{równoramienny} & 1 \\\\ \\text{różnoboczny} & 0 \\end{array} \\qquad \\begin{array}{ll} \\text{pięciokąt foremny} & 5 \\\\ \\text{sześciokąt foremny} & 6 \\\\ \\text{okrąg} & \\infty \\end{array}",
